package vn.iotstar.service.impl;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.stereotype.Service;import vn.iotstar.service.EmailService;@Service public class EmailServiceImpl implements EmailService{public EmailServiceImpl(JavaMailSender sender){this.sender=sender;}final JavaMailSender sender;public void sendOtp(String e,String o,String s){SimpleMailMessage m=new SimpleMailMessage();m.setTo(e);m.setSubject(s);m.setText("Xin chào,\n\nMã OTP của bạn là: "+o+"\n\nOTP có hiệu lực trong 5 phút.");sender.send(m);}}
